function sync(){onSnapshot(collection(db,'seasons'),s=>{if(!s.empty)state.seasons=s.docs.map(d=>normalizeSeason({id:d.id,...d.data()}));render()});onSnapshot(doc(db,'settings','app'),s=>{if(s.exists()){state.activeSeasonId=s.data().activeSeasonId||DEFAULT_SEASON_ID;if(!localStorage.getItem('r32_selected_season_id'))state.selectedSeasonId=state.activeSeasonId;refreshSeasonScope();render()}});onSnapshot(collection(db,'playerSeasons'),s=>{state.playerSeasons=s.docs.map(d=>({id:d.id,...d.data()}));refreshSeasonScope();render()});onSnapshot(collection(db,'players'),s=>{state.allPlayers=s.docs.map(d=>({id:d.id,...d.data()}));refreshSeasonScope();render()});onSnapshot(collection(db,'opponentTeams'),s=>{state.opponentTeams=s.docs.map(d=>({id:d.id,...d.data()}));render()});onSnapshot(collection(db,'games'),s=>{state.allGames=s.docs.map(d=>({id:d.id,...d.data()}));refreshSeasonScope();render()});onSnapshot(collection(db,'stats'),s=>{state.stats=s.docs.map(d=>({id:d.id,...d.data()}));$('#cloudStatus').textContent='クラウド接続済み';render()})}
