function teamTargetGames(){const games=filterByAggregationCondition(opponentFilteredGames('team'),state.teamMode,state.teamTargetId,state.teamPeriodStart,state.teamPeriodEnd);return gamesWithStats(filterByRegisteredGameCategory(games,state.teamCategoryId))}
