window.backOpponentTeams=()=>{const position=state.opponentTeamListReturnPosition;state.selectedOpponentTeamId='';state.tab='opponentTeams';render();setTimeout(()=>{const card=position?.id?opponentTeamListCard(position.id):null;if(card&&Number.isFinite(position?.top))window.scrollBy(0,card.getBoundingClientRect().top-position.top);else if(Number.isFinite(position?.scrollY))window.scrollTo(0,position.scrollY);state.opponentTeamListReturnPosition=null},0)}
function opponentTeamCardsHtml(teams){return teams.map(team=>`<div class="card opponent-team-card" role="button" tabindex="0" data-opponent-team-id="${escapeHtml(team.id)}" onclick="openOpponentTeamDetail('${team.id}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openOpponentTeamDetail('${team.id}')}"><div><h3>${escapeHtml(team.teamName)}</h3><div class="opponent-team-meta"><span>${escapeHtml(team.prefecture||'都道府県未設定')}</span><span>チームランク：${team.calculatedRank||'未設定'}</span><span>大会順位登録：${opponentPlacements(team).length}件</span><span>選手№：${sortPlayerNumbers(team.playerNumbers).join('、')||'未登録'}</span></div></div>${state.user?`<button class="btn ghost" onclick="event.stopPropagation();editOpponentTeam('${team.id}')">編集</button>`:''}</div>`).join('')||'<div class="card"><p class="sub">検索条件に該当する対戦チームはありません</p></div>'}
function refreshOpponentTeamResults(){const teams=visibleOpponentTeams(),list=$('.opponent-team-list'),count=$('.opponent-team-result-count');if(list)list.innerHTML=opponentTeamCardsHtml(teams);if(count)count.textContent=`${teams.length}件`}
function opponentTeamsView(){const prefectures=[...new Set(state.opponentTeams.map(team=>team.prefecture).filter(Boolean))].sort((a,b)=>PREFECTURES.indexOf(a)-PREFECTURES.indexOf(b)||a.localeCompare(b,'ja')),teams=visibleOpponentTeams();return `<div class="analysis-screen"><div class="analysis-title"><h2>対戦チーム <small>OPPONENT TEAMS</small></h2></div><div class="card opponent-team-list-header"><div class="section-title">対戦チーム一覧</div><div class="opponent-team-tools"><label>チーム名検索<input id="opponentTeamSearch" type="search" value="${escapeHtml(opponentTeamSearch)}" placeholder="チーム名を入力"></label><label>都道府県<select id="opponentPrefectureFilter"><option value="">すべて</option>${prefectures.map(pref=>`<option value="${escapeHtml(pref)}" ${pref===opponentPrefectureFilter?'selected':''}>${escapeHtml(pref)}</option>`).join('')}<option value="未設定" ${opponentPrefectureFilter==='未設定'?'selected':''}>未設定</option></select></label><label>表示順<select id="opponentTeamSort"><option value="name" ${opponentTeamSort==='name'?'selected':''}>名前順</option><option value="rank" ${opponentTeamSort==='rank'?'selected':''}>ランク順（高い順）</option></select></label></div><div class="opponent-team-result-count">${teams.length}件</div>${state.user?'<div class="row"><button class="btn" id="addOpponentTeam">＋ 新規対戦チーム登録</button></div>':'<p class="sub">登録・編集には管理者ログインが必要です。</p>'}</div><div class="opponent-team-list">${opponentTeamCardsHtml(teams)}</div></div>`}
