    const imported=TEAMS_2026_WAKAYAMA_U15_MEN[index];
    const candidates=existingByName.get(imported.normalizedTeamName)||[];
    const existing=candidates.find(team=>!String(team.id||'').startsWith(`${tournament.id}-`))||candidates[0];
    const id=existing?.id||`${tournament.id}-${String(index+1).padStart(2,'0')}`;
    const current=opponentPlacements(existing);
    const previous=current.find(item=>item.tournamentId===tournament.id&&Number(item.year)===tournament.year);
    const placement={id:`${id}-${tournament.id}`,tournamentId:tournament.id,tournamentName:tournament.name,year:tournament.year,placement:imported.placementLabel,placementLabel:imported.placementLabel,numericPlacement:imported.placement,wins:imported.wins,placementRank:imported.rank,rankValue:imported.rank,sortOrder:previous?.sortOrder??current.length,sourceType:'officialTournamentPdf',resultConfirmed:true,updatedAt:new Date().toISOString()};
    const placements=previous?current.map(item=>item===previous?{...item,...placement}:item):[...current,{...placement,createdAt:new Date().toISOString()}];
