    const ref=doc(db,'tournamentGames',id),snapshot=await getDoc(ref);
    const teamA=teamByName.get(item.teamA),teamB=teamByName.get(item.teamB),winner=teamByName.get(item.winner),loser=teamByName.get(item.loser);
