function bindHistoryDrag(game){const list=$('#gameHistoryList'),scroller=document.querySelector('#modalRoot .game-history-modal');if(!list||!scroller)return;let row=null,pointerId=null,raf=0,direction=0;const auto=()=>{if(!row||!direction){raf=0;return}scroller.scrollTop+=direction*12;const target=document.elementFromPoint(innerWidth/2,direction>0?scroller.getBoundingClientRect().bottom-22:scroller.getBoundingClientRect().top+22)?.closest?.('[data-history-event-id]');if(target&&target!==row)list.insertBefore(row,direction>0?target.nextSibling:target);raf=requestAnimationFrame(auto)};const stop=async()=>{if(!row)return;row.classList.remove('dragging');row=null;pointerId=null;direction=0;if(raf)cancelAnimationFrame(raf);raf=0;try{await saveHistoryOrder(game)}catch(error){console.error(error);toast('履歴順の保存に失敗しました')}};list.querySelectorAll('[data-history-drag]').forEach(handle=>handle.onpointerdown=event=>{row=handle.closest('[data-history-event-id]');pointerId=event.pointerId;handle.setPointerCapture?.(pointerId);row.classList.add('dragging');event.preventDefault()});list.onpointermove=event=>{if(!row||event.pointerId!==pointerId)return;const bounds=scroller.getBoundingClientRect();direction=event.clientY>bounds.bottom-70?1:event.clientY<bounds.top+70?-1:0;if(direction&&!raf)raf=requestAnimationFrame(auto);const target=document.elementFromPoint(event.clientX,event.clientY)?.closest?.('[data-history-event-id]');if(target&&target!==row&&target.parentElement===list){const box=target.getBoundingClientRect();list.insertBefore(row,event.clientY>box.top+box.height/2?target.nextSibling:target)}};list.onpointerup=stop;list.onpointercancel=stop}
